#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-29
# ============================================================================
# Permission Rule Shapes
# ============================================================================
# CC 2.1.246 started warning at startup about Bash allow rules with a wildcard
# BEFORE the subcommand, e.g. `Bash(git * main)`: the glob also matches options
# inserted before the subcommand (`git -c x=y push main`), so the rule grants
# more than it reads. ork ships its permission rules to every user through
# src/settings/*.settings.json; a rule of that shape would put CC's warning in
# every user's startup output and widen an allow silently.
#
# Scope: every `permissions.allow|deny|ask` entry in src/settings/*.settings.json
# whose tool is Bash. A rule is BAD when a `*` is followed by whitespace and
# then more pattern text inside the parentheses. A trailing `*` (`Bash(git *)`)
# is fine; so is `Bash(* && rm -rf *)` where the leading star stands for the
# whole first command (that shape is a deny, and widening a deny is the safe
# direction; the check is applied to allow rules only for exactly that reason,
# and to deny/ask only as an informational count).
#
# Measured 2026-08-29 at adoption: 0 of 55 rules across the three settings
# files have the shape. This test exists so that stays true.
#
# Positive control: the regex is exercised against a known-bad literal at the
# end, so a broken pattern fails the test instead of passing vacuously.

set -euo pipefail
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PASS=0; FAIL=0
log_pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
log_fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1: $2"; }

echo "=========================================="
echo "  Permission Rule Shapes (CC 2.1.246)"
echo "=========================================="

# Matches a Bash rule whose '*' is followed by whitespace and more text before ')'.
BAD_RE='^Bash\([^)]*\*[[:space:]]+[^)[:space:]]'

files=("$PROJECT_ROOT"/src/settings/*.settings.json)
[[ ${#files[@]} -gt 0 ]] || { log_fail "settings files" "none found under src/settings"; }

total=0; bad=0; informational=0
for f in "${files[@]}"; do
  [[ -f "$f" ]] || continue
  # node: exact JSON parse, one rule per line as "<list>\t<rule>"
  while IFS=$'\t' read -r list rule; do
    [[ -n "$rule" ]] || continue
    total=$((total + 1))
    if [[ "$rule" =~ $BAD_RE ]]; then
      if [[ "$list" == "allow" ]]; then
        log_fail "wildcard before subcommand in an allow rule" "${f#"$PROJECT_ROOT"/}: $rule"
        bad=$((bad + 1))
      else
        informational=$((informational + 1))
        echo "  · info: $list rule has a wildcard before its subcommand (safe direction): $rule"
      fi
    fi
  done < <(node -e '
    const fs = require("fs");
    const s = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
    const p = s.permissions || {};
    for (const list of ["allow", "deny", "ask"]) {
      for (const r of (p[list] || [])) {
        if (typeof r === "string" && r.startsWith("Bash(")) process.stdout.write(list + "\t" + r + "\n");
      }
    }' "$f")
done

if [[ $bad -eq 0 ]]; then
  log_pass "no allow rule with a wildcard before its subcommand across $total Bash rule(s) in ${#files[@]} settings file(s) ($informational informational in deny/ask)"
fi

# Positive control: the pattern must catch the documented bad shape and must
# leave the documented fine shapes alone.
if [[ "Bash(git * main)" =~ $BAD_RE ]]; then
  log_pass "positive control: Bash(git * main) is caught"
else
  log_fail "positive control" "Bash(git * main) was NOT caught; the pattern is broken"
fi
for ok in "Bash(git *)" "Bash(npm run build)" "Bash(gh pr *)"; do
  if [[ "$ok" =~ $BAD_RE ]]; then
    log_fail "negative control" "$ok was flagged but is a fine shape"
  fi
done
log_pass "negative controls: trailing-star and literal rules are not flagged"

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ $FAIL -eq 0 ]] || exit 1
